input.oldString:
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const lines = text.split('\n');
  const messages: string[] = [];
  const currentMessage: string[] = [];
  let currentLength = 0;

  for (const line of lines) {
    const lineLength = line.length + 1; // newline except possibly last

    if (currentLength === 0) {
      // First line in a new message
      if (line.length > limit) {
        // Line too long: cut it into chunks
        const chunks = chunkLine(line, limit);
        for (let i = 0; i < chunks.length; i++) {
          if (i > 0) {
            messages.push(messages.pop()! + '\n' + chunks[i]);
          } else {
            currentMessage.push(chunks[i]);
            currentLength = chunks[i].length;
          }
        }
      } else {
        currentMessage.push(line);
        currentLength = lineLength;
      }
    } else {
      if (lineLength > limit) {
        // Line too long: cut it and attach remainder to current message if possible
        const chunks = chunkLine(line, limit);
        if (currentLength < limit && chunks.length > 1) {
          currentMessage.push(chunks[0]);
          currentLength += chunks[0].length + 1;
          for (let i = 1; i < chunks.length; i++) {
            messages.push('\n' + chunks[i]);
          }
          if (chunks.length === 1 && currentLength > limit) {
            // Need to move the overflow to a new message
            const overflowLength = currentLength - limit;
            const adjustedChunks = line.split('').reverse().slice(0, overflowLength).reverse().join('');
            messages.push(adjustedChunks);
            const remaining = line.replace(adjustedChunks, '').trim();
            currentMessage.push(remaining);
            currentLength = remaining.length;
          }
        } else {
          for (const chunk of chunks) {
            messages.push(chunk);
          }
        }
        currentMessage.length = 0;
        currentLength = 0;
      } else if (currentLength + lineLength <= limit) {
        currentMessage.push(line);
        currentLength += lineLength;
      } else {
        if (currentMessage.length > 0) {
          messages.push(currentMessage.join('\n'));
        }
        currentMessage.push(line);
        currentLength = lineLength;
      }
    }
  }

  if (currentMessage.length > 0) {
    messages.push(currentMessage.join('\n'));
  }

  return messages;
}

