export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  // Split text into blocks separated by blank lines (one or more newlines)
  const blocks = text.split(/\n\s*\n/);

  const messages: string[] = [];
  let currentMessage: string[] = [];
  let currentLength = 0;

  for (const block of blocks) {
    const blockWithNewline = block + '\n';
    // Check if block fits standalone
    if (block.length <= limit) {
      if (currentMessage.length === 0) {
        currentMessage.push(block);
        currentLength = block.length;
      } else if (currentMessage.length + 1 + block.length <= limit) {
        currentMessage.push('\n' + block);
        currentLength += 1 + block.length;
      } else {
        // New message needed
        if (currentMessage.length > 0) {
          messages.push(currentMessage.join('\n'));
        }
        currentMessage.push(block);
        currentLength = block.length;
      }
    } else {
      // Block longer than limit - split it by lines
      const blockLines = block.split('\n');
      const blockIsSingleLine = blockLines.length === 1;

      if (blockIsSingleLine) {
        // Single line longer than limit - cut it
        let chars = block;
        // Remove trailing newline for processing
        if (block.endsWith('\n')) {
          chars = block.slice(0, -1);
        }
        const chunks = chunkLine(chars, limit);
        let chunkNum = 0;
        for (const chunk of chunks) {
          if (chunkNum === 0) {
            if (currentMessage.length === 0) {
              currentMessage.push(chunk);
              currentLength = chunk.length;
            } else if (currentLength + 1 + chunk.length <= limit) {
              currentMessage.push('\n' + chunk);
              currentLength += 1 + chunk.length;
            } else {
              if (currentMessage.length > 0) {
                messages.push(currentMessage.join('\n'));
              }
              currentMessage.push(chunk);
              currentLength = chunk.length;
            }
            chunkNum++;
          } else {
            if (currentMessage.length > 0) {
              messages.push(currentMessage.join('\n'));
            }
            if (chunkNum === 1 && block !== '') {
              messages.push(chunk);
            } else {
              messages.push('\n' + chunk);
            }
          }
        }
        currentMessage.length = 0;
        currentLength = 0;
      } else {
        // Multi-line block where at least one line exceeds limit
        for (const line of blockLines) {
          const lineLength = line.length + 1;
          if (line.length > limit) {
            const chunks = chunkLine(line, limit);
            let chunkNum = 0;
            for (const chunk of chunks) {
              if (chunkNum === 0) {
                if (currentLength + 1 + chunk.length <= limit) {
                  if (chunkNum === 0 && currentMessage.length > 0) {
                    currentMessage.push('\n' + chunk);
                  } else {
                    currentMessage.push(chunk);
                  }
                  currentLength += chunk.length + (chunkNum === 0 && currentMessage.length > 0 ? 1 : 0);
                } else {
                  if (currentMessage.length > 0 && chunkNum > 0) {
                    messages.push(currentMessage.join('\n'));
                  }
                  // First chunk of this long line
                  currentMessage.push(chunk);
                  currentLength = chunk.length;
                  chunkNum++;
                }
              } else {
                if (currentMessage.length > 0) {
                  messages.push(currentMessage.join('\n'));
                }
                messages.push(chunk);
                chunkNum++;
              }
            }
            currentMessage.length = 0;
            currentLength = 0;
          } else {
            // This line fits
            const lineLength = line.length + 1;
            if (currentLength === 0) {
              currentMessage.push(line + (blockLines[line.indexOf(line) + 1] !== undefined ? '\n' : ''));
              currentLength = line.length + (blockLines[line.indexOf(line) + 1] !== undefined ? 1 : 0);
            } else if (currentLength + lineLength <= limit) {
              currentMessage.push('\n' + line);
              currentLength += 1 + line.length;
            } else {
              if (currentMessage.length > 0) {
                messages.push(currentMessage.join('\n'));
              }
              currentMessage.push(line + (blockLines[line.indexOf(line) + 1] !== undefined ? '\n' : ''));
              currentLength = line.length + (blockLines[line.indexOf(line) + 1] !== undefined ? 1 : 0);
            }
          }
        }
      }
    }
  }

  if (currentMessage.length > 0) {
    messages.push(currentMessage.join('\n'));
  }

  return messages;
}

