export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const lines = text.split('\n');
  const messages: string[] = [];
  const currentMessage: string[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const isLastLine = i === lines.length - 1;
    const nextLine = isLastLine ? undefined : lines[i + 1];

    // Check if two consecutive lines fit in one message
    const fitWithNext = !isLastLine && line.length + 1 + nextLine.length + 1 <= limit;

    // Check if this line alone fits
    const fitsAlone = line.length + (!isLastLine) <= limit;

    if (fitWithNext) {
      // Take both lines together
      currentMessage.push(line);
      currentMessage.push('\n' + nextLine);
      i++;
    } else if (fitsAlone) {
      currentMessage.push(line);
    } else {
      // This line is too long, cut it
      const chunks = chunkLine(line, limit);
      for (let j = 0; j < chunks.length; j++) {
        if (j === 0) {
          // First chunk - try to append to current message
          if (currentMessage.length === 0) {
            currentMessage.push(chunks[j]);
          } else {
            // Check if fits after what we have
            const potential = currentMessage.join('\n');
            if (potential.length + 1 + chunks[j].length <= limit) {
              currentMessage.push('\n' + chunks[j]);
            } else {
              // Start new message
              if (currentMessage.length > 0) {
                messages.push(currentMessage.join('\n'));
              }
              currentMessage.push(chunks[j]);
            }
          }
        } else {
          // Remaining chunks - each goes to own message
          if (currentMessage.length > 0) {
            messages.push(currentMessage.join('\n'));
          }
          messages.push(chunks[j]);
          // If this is the last chunk and text ended, ensure it's part of a message
          if (j === chunks.length - 1 && nextLine === undefined) {
            // This is the end of text
          } else if (j === chunks.length - 1) {
            // Last chunk but not end of text - might need to handle next line
            // For now, keep it simple: start new message for next iteration
          }
          currentMessage.length = 0;
        }
      }
      currentMessage.length = 0;
    }
  }

  if (currentMessage.length > 0) {
    messages.push(currentMessage.join('\n'));
  }

  return messages;
}

