input.newString:
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  // Split by blank lines to get blocks - blocks won't be split internally
  const blocks = text.split(/\n\n+/);

  const messages: string[] = [];
  let currentMessage: string[] = [];
  let currentLength = 0;

  for (const rawBlock of blocks) {
    // Check if block fits in current message
    const blockLength = rawBlock.length;

    if (currentMessage.length === 0) {
      // Starting a new message
      if (blockLength <= limit) {
        // Block fits cleanly
        currentMessage.push(rawBlock);
        currentLength = blockLength;
      } else {
        // Block exceeds limit - process line by line
        const result = splitLines(rawBlock, limit, false);
        if (result.messages.length > 0) {
          messages.push(...result.messages);
        }
        currentMessage.push(result.remaining);
        currentLength = result.remaining.length;
      }
    } else {
      if (currentLength + 1 + blockLength <= limit) {
        // Fits with blank line separator
        currentMessage.push('\n\n' + rawBlock);
        currentLength += 1 + blockLength;
      } else if (currentLength + blockLength <= limit) {
        // No separator but still fits
        currentMessage.push(rawBlock);
        currentLength += blockLength;
      } else {
        // Doesn't fit - start new message
        if (currentMessage.length > 0) {
          messages.push(currentMessage.join('\n'));
        }
        const result = splitLines(rawBlock, limit, true);
        if (result.messages.length > 0) {
          messages.push(...result.messages);
        }
        currentMessage.push(result.remaining);
        currentLength = result.remaining.length;
      }
    }
  }

  if (currentMessage.length > 0) {
    messages.push(currentMessage.join('\n'));
  }

  return messages;
}

function splitLines(text: string, limit: number, firstInMessage: boolean): { messages: string[]; remaining: string } {
  const lines = text.split('\n');
  const messages: string[] = [];
  let remaining = '';

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.length > limit) {
      // Line too long - chunk it
      const chunks = chunkLine(trimmed, limit);
      const totalChunkLength = chunks.reduce((sum, c) => sum + c.length + 1, 0);

      if (firstInMessage && currentMessage.length === 0) {
        // Will handle this case separately
      }

      let chunkIndex = 0;
      for (const chunk of chunks) {
