            // Last chunk but not end of text - might need to handle next line
            // For now, keep it simple: start new message for next iteration
          }
          currentMessage.length = 0;
        }
      }
      currentMessage.length = 0;
    }
  }

  if (currentMessage.length > 0) {
    messages.push(currentMessage.join('\n'));
  }

  return messages;
}

