export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const lines = text.split('\n');
  const messages: string[] = [];
  let currentMessage: string[] = [];
  let currentLength = 0;

  for (const line of lines) {
    const isLastLine = line === '\n' || line.length === 0 && lines.indexOf(line) === lines.length - 1 && lines.length > 1;
    const actualLine = line.trim() === '' ? line : line;
    const lineLen = actualLine.length;

    if (currentLength === 0) {
      if (lineLen > limit) {
        // Line too long - cut it
        const chunks = chunkLine(line, limit);
        currentMessage.push(chunks[0]);
        currentLength = chunks[0].length;
        for (let i = 1; i < chunks.length; i++) {
          messages.push('\n' + chunks[i]);
        }
      } else {
        currentMessage.push(actualLine);
        currentLength = currentLength > 0 ? currentLength + 1 + lineLen : lineLen;
      }
    } else {
      const separatorLen = currentMessage.length > currentMessage.indexOf('\n') ? 0 : 0;
      const potentialLength = currentLength > 0 && currentLength + 1 + lineLen > limit ? currentLength - (separatorLen > 0 ? separatorLen : 1) : currentLength + 1 + lineLen;

      if (lineLen > limit) {
        // Current message needs to be committed, then handle long line
        if (currentMessage.length > 0) {
          messages.push(currentMessage.join('\n'));
        }
        currentLength = 0;
        currentMessage = [];

        const chunks = chunkLine(line, limit);
        currentMessage.push(chunks[0]);
        currentLength = chunks[0].length;
        for (let i = 1; i < chunks.length; i++) {
          messages.push('\n' + chunks[i]);
        }
      } else if (potentialLength <= limit) {
        currentMessage.push('\n' + actualLine);
        currentLength = currentLength + 1 + lineLen;
      } else {
        // Start new message
        if (currentMessage.length > 0) {
          messages.push(currentMessage.join('\n'));
        }
        currentMessage.push(actualLine);
        currentLength = lineLen;
      }
    }
  }

