        if (messages.length === 0) {
          if (chunkLength <= limit) {
            messages.push(chunkWithSep);
          }
        } else {
          const potential = messages[messages.length - 1];
          const fit = potential.length + 1 + chunkLength <= limit;
          if (fit) {
            messages[messages.length - 1] = potential + '\n' + chunk;
          } else {
