import { DISCORD_MESSAGE_MAX_LENGTH } from '../utils/constants.js';
import type { Client, TextChannel, User } from 'discord.js';
import { getDb } from '../db/index.js';
import { digestLog, type ListingRow, type ServerRow } from '../db/schema.js';
import { DIGEST_SECTION_CAP } from '../utils/constants.js';
import type { DigestTrigger } from '../types/index.js';
import { digestLine } from '../utils/embeds.js';
import { prepareDigestListings, setServerWatermark } from './digest-state.js';
import { sendCriticalAlert } from './alerts.js';
import { retryWithBackoff } from '../utils/retry.js';

const now = () => Date.now();

export interface DigestResult {
  sent: boolean;
  channelOk: boolean;
  dmOk: boolean;
  listingCount: number;
}

/**
 * Format a digest message body from the collected listings, grouped by type.
 * Each section is capped and overflows are noted.
 */
export function formatDigest(listingsToShow: ListingRow[]): string {
  const groups = {
    have: listingsToShow.filter((l) => l.intent === 'have'),
    want: listingsToShow.filter((l) => l.intent === 'want'),
  };

  const sections: string[] = [];
  const pushSection = (title: string, rows: ListingRow[]): void => {
    if (rows.length === 0) {
      return;
    }
    const shown = rows.slice(0, DIGEST_SECTION_CAP);
    const lines = shown.map(digestLine).join('\n');
    const overflow =
      rows.length > DIGEST_SECTION_CAP ? `\n+${rows.length - DIGEST_SECTION_CAP} more` : '';
    sections.push(`${title} (${rows.length})\n${lines}${overflow}`);
  };

  pushSection('NEW HAVES', groups.have);
  pushSection('NEW WANTS', groups.want);

  return sections.join('\n\n');
}

/**
 * Split a digest message into chunks that fit within the Discord message length limit.
 * - Text that fits within limit comes back unchanged as a one-element array.
 * - Overflows are split into messages, each ≤ limit, preserving order and content.
 * - Blocks separated by blank lines are not split; if a block fits, it stays whole.
 * - If a block doesn't fit, it starts a new message.
 * - Lines longer than limit are cut into consecutive chunks of exactly limit chars
 *   (last chunk holds the remainder).
 * @param text - The full message text to split.
 * @param limit - Maximum characters per message (default: DISCORD_MESSAGE_MAX_LENGTH).
 * @returns Array of message strings, each ≤ limit, in order.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  // Split text into blocks by one or more blank lines
  const blocks = text.split(/\n{2,}/);

  const messages: string[] = [];
  let currentMessage: string[] = [];
  let currentLength = 0;

  for (const block of blocks) {
    const blockLines = block.split('\n');
    let blockText = block;

    if (currentMessage.length === 0) {
      // First block goes into current message
      const len = block.length;
      if (len <= limit) {
        currentMessage.push(block);
        currentLength = len;
      } else {
        // Block too long - split by lines
        for (let i = 0; i < blockLines.length; i++) {
          const line = blockLines[i];
          const lineLen = line.length;
          const isLast = i === blockLines.length - 1;

          if (lineLen > limit) {
            // Line too long - cut it
            const chunks = chunkLine(line, limit);
            const chunkLen = chunks.reduce((sum, c, idx) => sum + (idx > 0 ? 1 : 0) + c.length, 0);
            let lastIdx = chunks.length - 1;

            if (chunkLen > limit) {
              // Even chunks exceed limit, truncate last
              const trimmed = chunks[lastIdx];
              while (trimmed.length > 0 && currentLength + 1 + trimmed.length > limit) {
                trimmed = trimmed.substring(0, trimmed.length - 1);
              }
              if (trimmed.length === 0 && chunks.length > 1) {
                trimmed = chunks[lastIdx - 1] + '...';
                chunks.length = lastIdx;
              }
            }
            currentMessage.push(chunks[0]);
            currentLength = chunks[0].length;
            lastIdx = chunks.length - 1;
            for (; i < chunks.length - 1; i++) {
              messages.push('\n' + chunks[i]);
            }
            if (chunks.length > 0) {
              currentMessage.push(chunks[chunks.length - 1]);
              currentLength += chunks[chunks.length - 1].length;
            }
            break;
          } else {
            // Line fits
            currentMessage.push(line);
            currentLength += isLast ? lineLen : lineLen + 1;
          }
        }
      }
    } else {
      // Subsequent blocks
      const remainingInCurrent = limit - currentLength;

      if (block.length <= remainingInCurrent) {
        // Block fits in current message
        currentMessage.push('\n' + block);
        currentLength += 1 + block.length;
      } else if (remainingInCurrent > 0) {
        // Push what fits to current message
        const remainingInCurrentAfterHeader = Math.floor(remainingInCurrent / (lines.flat(false).length));
        // Try remaining line after the last one
        const lastLineIndex = currentMessage.length - 1;
        const nextLineIndex = lastLineIndex >= 0 ? lines[lastLineIndex + 1]['index'] : 1;
        const nextLineLength = lines[lastLineIndex + 1]['index'] !== 1 ? 1 : 0;

        currentMessage.push('\n');
        currentLength += 1;

        const chunksNextLine = chunkLine(lines[lastLineIndex + 1], lastLineIndex + 1)];
        if (chunksNextLine.length > 0 && chunksNextLine.length <= remainingInCurrent) {
          currentMessage.push(chunksNextLine[0]);
          currentLength += 1;
          for (let idx = 0; idx < chunksNextLine.length - 1; idx++) {
            messages.push('\n' + chunksNextLine[idx]);
          }
          if (chunksNextLine.length > 0) {
            currentMessage.push(chunksNextLine[chunksNextLine.length - 1]);
            currentLength += chunksNextLine[chunksNextLine.length - 1].length;
          }
        }

        currentMessage.push('\n' + block);
        currentLength += 1 + block.length;
      } else {
        // Start a new message with this block
        if (currentMessage.length > 0) {
          messages.push(currentMessage.join('\n'));
        }
        currentMessage.push(block);
        currentLength = block.length; // Note: block.length may exceed limit
      }
    }
  }

  if (currentMessage.length > 0) {
    messages.push(currentMessage.join('\n'));
  }

  return messages;
}

function chunkLine(line: string, limit: number): string[] {
  const chunks: string[] = [];
  const chars = line.split('');

  for (let i = 0; i < chars.length; i += limit) {
    const chunk = chars.slice(i, i + limit).join('');
    chunks.push(chunk);
  }

  return chunks;
}

function chunkLine(line: string, limit: number): string[] {
  const chunks: string[] = [];
  const chars = line.split('');

  for (let i = 0; i < chars.length; i += limit) {
    chunks.push(chars.slice(i, i + limit).join(''));
  }

  return chunks;
}

/**
 * Run a digest for one server. Follows the watermark rules in the spec: only
 * listings created after `last_digest_at` are selected, delivery is by
 * `digest_mode`, and the watermark only advances when at least one destination
 * succeeds.
 */
export async function runDigest(
  client: Client,
  server: ServerRow,
  trigger: DigestTrigger,
): Promise<DigestResult> {
  const collected = prepareDigestListings(server);

  const empty: DigestResult = { sent: false, channelOk: false, dmOk: false, listingCount: 0 };
  if (collected.length === 0) {
    return empty;
  }

  const heading = `Daily Listing Digest — ${new Date(now()).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  })}`;
  const message = `${heading}\n\n${formatDigest(collected)}`;

  let channelOk = false;
  let dmOk = false;
  const messages = splitDigestMessage(message);
  const channelMessages = messages.filter((_, i) => i % 2 === 0);
  const dmMessages = messages.filter((_, i) => i % 2 === 0);
  if (server.digestMode === 'channel' || server.digestMode === 'both') {
    channelOk = await deliverToChannels(client, server, messages);
  }
  if (server.digestMode === 'dm' || server.digestMode === 'both') {
    dmOk = await deliverToDMs(client, server, messages);
  }

  if (!channelOk && !dmOk) {
    // No destination succeeded; record the failure and leave the watermark
    // unchanged so the same listings are retried next time.
    logDigest(server.id, trigger, collected, { channel: false, dm: false });
    sendCriticalAlert(`Digest delivery failed for server ${server.id}`);
    return { sent: false, channelOk, dmOk, listingCount: collected.length };
  }

  setServerWatermark(server.id, now());
  logDigest(server.id, trigger, collected, { channel: channelOk, dm: dmOk });
  return { sent: true, channelOk, dmOk, listingCount: collected.length };
}

async function deliverToChannels(
  client: Client,
  server: ServerRow,
  messages: string[],
): Promise<boolean> {
  if (!server.adminChannelId || messages.length === 0) {
    return false;
  }
  try {
    const channel = (await client.channels.fetch(server.adminChannelId)) as TextChannel | null;
    if (!channel || !channel.isTextBased() || !channel.isSendable()) {
      return false;
    }
    let allOk = true;
    for (const message of messages) {
      await retryWithBackoff(
        () => channel.send({ content: message, allowedMentions: { parse: [] } }),
        {
          attempts: 3,
          baseDelayMs: 1000,
          maxDelayMs: 8000,
        },
      );
    }
    return true;
  } catch {
    return false;
  }
}

async function deliverToDMs(client: Client, server: ServerRow, messages: string[]): Promise<boolean> {
  if (!server.digestDmUserId || messages.length === 0) {
    return false;
  }
  try {
    const user = (await client.users.fetch(server.digestDmUserId)) as User | null;
    if (!user) {
      return false;
    }
    let allOk = true;
    for (const message of messages) {
      await retryWithBackoff(() => user.send({ content: message, allowedMentions: { parse: [] } }), {
        attempts: 3,
        baseDelayMs: 1000,
        maxDelayMs: 8000,
      });
    }
    return true;
  } catch {
    return false;
  }
}

function logDigest(
  serverId: string,
  trigger: DigestTrigger,
  included: ListingRow[],
  results: { channel: boolean; dm: boolean },
): void {
  const db = getDb();
  db.insert(digestLog)
    .values({
      serverId,
      sentAt: now(),
      trigger,
      listingCount: included.length,
      listingIdsIncluded: JSON.stringify(included.map((l) => l.id)),
      deliveryResults: JSON.stringify(results),
    })
    .run();
}

