    return [text];
  }

  // Get all lines, preserving empty lines as-is
  const allLines: string[] = [];
  let cur = '';
  for (const ch of text) {
    if (ch === '\n') {
      if (cur.endsWith('\n')) {
        allLines.push(cur);
      } else if (cur.length > 0 && cur !== '') {
        allLines.push(cur);
      } else if (cur.length === 0) {
        allLines.push('\n');
      }
      cur = '';
    } else {
      cur += ch;
    }
  }
  if (cur.length > 0) {
    allLines.push(cur.endsWith('\n') ? cur.slice(0, -1) : cur);
  }

  const messages: string[] = [];
  const current: string[] = [];
  let currentLen = 0;

  for (let i = 0; i < allLines.length; i++) {
    const line = allLines[i];
    const isLast = i === allLines.length - 1;
    const nextLine = i < allLines.length - 1 ? allLines[i + 1] : undefined;
    const nextLineIsEmpty = nextLine !== undefined && nextLine === '';
    const nextLineIsBreak = nextLine !== undefined && /^$/.test(nextLine);
    const thisLineIsBreakLine = /^\s*$/.test(line);

    if (thisLineIsBreakLine) {
      // A blank line - end current block if we're building one
      if (currentLen === 0 && i > 0 && allLines[i - 1].length > 0) {
        // Just blank lines now, nothing to do
        continue;
      }
      if (currentLen > 0 && nextLineIsBreak || (currentLen > 0 && !nextLine)) {
        // Committed a non-empty block
      }
    }

    if (currentLen === 0) {
      // Starting a new message
      const len = line.length;
      if (len > limit) {
        // Line too long - cut it
        const chunks = chunkString(line, limit);
        for (let j = 0; j < chunks.length; j++) {
          const c = chunks[j];
          const sep = j === 0 ? '' : (messages.length > 0 ? '\n' : '');
          if (messages.length === 0) {
            current.push(c);
            currentLen = c.length;
          } else if (c.length <= limit) {
            current.push(c);
            currentLen = c.length;
          }
        }
      } else {
        current.push(line);
        currentLen = len;
      }
    } else {
      // Try to fit this line
      if (thisLineIsBreakLine) {
        // Blank line - only keep if we're not at the end
        if (i < allLines.length - 1) {
          current.push(line);
          currentLen = currentLen > 0 ? currentLen + 1 + 0 : 0;
        }
      } else {
        const withNewlines = currentLen > 0 && !isLast ? currentLen + 1 + line.length : currentLen;
        if (withNewlines <= limit) {
