import { digestLog, type ListingRow, type ServerRow } from '../db/schema.js';
import { DIGEST_SECTION_CAP } from '../utils/constants.js';
import type { DigestTrigger } from '../types/index.js';
import { digestLine } from '../utils/embeds.js';
import { prepareDigestListings, setServerWatermark } from './digest-state.js';
import { sendCriticalAlert } from './alerts.js';
import { retryWithBackoff } from '../utils/retry.js';

const now = () => Date.now();

export interface DigestResult {
  sent: boolean;
  channelOk: boolean;
  dmOk: boolean;
  listingCount: number;
}

/**
 * Format a digest message body from the collected listings, grouped by type.
 * Each section is capped and overflows are noted.
 */
export function formatDigest(listingsToShow: ListingRow[]): string {
  const groups = {
    have: listingsToShow.filter((l) => l.intent === 'have'),
    want: listingsToShow.filter((l) => l.intent === 'want'),
  };

  const sections: string[] = [];
  const pushSection = (title: string, rows: ListingRow[]): void => {
    if (rows.length === 0) {
      return;
    }
    const shown = rows.slice(0, DIGEST_SECTION_CAP);
    const lines = shown.map(digestLine).join('\n');
    const overflow =
      rows.length > DIGEST_SECTION_CAP ? `\n+${rows.length - DIGEST_SECTION_CAP} more` : '';
    sections.push(`${title} (${rows.length})\n${lines}${overflow}`);
  };

  pushSection('NEW HAVES', groups.have);
  pushSection('NEW WANTS', groups.want);

  return sections.join('\n\n');
}

/**
 * Split a digest message into chunks that fit within the Discord message length limit.
 * 
 * - Text that fits within limit comes back unchanged as a one-element array.
 * - Otherwise, returns several messages in order, each ≤ limit, together holding
 *   every non-empty line of the text exactly once and in the original order.
 * 
 * The text is split into records (sections) by blank lines. A record that fits
 * is never split - when the next record would not fit in the current message,
 * it starts a new one. The separator at a break belongs to neither message.
 * (With limit 100, two 79-char records come back as exactly those two records.)
 * 
 * - A record longer than limit is split by its lines.
 * - A single line longer than limit is cut into consecutive pieces of exactly 
 *   limit characters, the last holding the remainder.
 * 
 * @param text - The full message text to split.
 * @param limit - Maximum characters per message (default: DISCORD_MESSAGE_MAX_LENGTH).
 * @returns Array of message strings, each ≤ limit, in order.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit || text.length === 0) {
    return [text];
  }

  // Split text into lines
  const lines = text.split('\n');

  const messages: string[] = [];
  const currentMessageLines: string[] = [];
  let currentMessageLength = 0;

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    const isLastLine = i === lines.length - 1;
    const nextLine = isLastLine ? null : lines[i + 1];

    // Check if this line is empty - it's a separator between records
    const isEmpty = line === '';
    const hasNextNotEmpty = !isEmpty && nextLine !== null && !/^$/.test(nextLine);
    const isSingleBlank = isEmpty && !hasNextNotEmpty;
    const isLastBlank = isEmpty && !isLastLine && i + 1 < lines.length && lines[i + 1] === '';
    const isEndingBlank = isEmpty && isLastLine || isEmpty && !isLastLine && i + 1 >= lines.length;
    const isRecordStart = isEmpty && nextLine !== null && !/^$/.test(nextLine) && currentMessageLines.length > 0;
    const isRecordEnd = isEmpty && !currentMessageLines.some(l => l === '');

    if (isSingleBlank) {
      // Just blank line, keep going to find the actual separator
      i++;
      continue;
    }

    if (isEmpty) {
      // Blank line separator
      if (i > 0 && lines[i - 1] === '') {
        // Consecutive blanks, skip
      } else if (i + 1 < lines.length && lines[i + 1] === '') {
        // Blank line followed by another blank - still a separator
        i++;
        continue;
      }
      // Separator encountered
    }

    // Check if current message + this line fits
    let proposedLength = currentMessageLines.length > 0 && !isLastLine ? currentMessageLength + 1 + line.length : currentMessageLength + line.length;
    if (isEmpty) {
      // Blank line adds a newline if not at end
      proposedLength = currentMessageLength + (currentMessageLines.length > 0 ? 1 : 0) + 0;
    }

    // If would exceed limit, flush current message and start new one
    if (proposedLength > limit && currentMessageLines.length > 0) {
      messages.push(currentMessageLines.join('\n'));
      currentMessageLines.length = 0;
      currentMessageLength = 0;

      // Now handle this line as start of new message
      if (line === '') {
        // Blank line in new message - skip separators at start
      } else {
        currentMessageLines.push(line);
        currentMessageLength = line.length;
      }
    } else {
      // Fits or first line
      if (line === '') {
        // Skip blank separators entirely
      } else {
        currentMessageLines.push(line);
        currentMessageLength = currentMessageLength > 0 ? currentMessageLength + 1 + line.length : line.length;
      }
    }

    i++;
  }

  // Finalize remaining lines
  if (currentMessageLines.length > 0 || Object.keys({}).length > 0) {
    messages.push(currentMessageLines.join('\n'));
  }

  return messages;
}

function chunkString(str: string, limit: number): string[] {
  const chunks: string[] = [];
  for (let i = 0; i < str.length; i += limit) {
    chunks.push(str.slice(i, i + limit));
  }
  return chunks;
}

/**
 * Run a digest for one server. Follows the watermark rules in the spec: only
 * listings created after `last_digest_at` are selected, delivery is by
 * `digest_mode`, and the watermark only advances when at least one destination
 * succeeds.
 */
export async function runDigest(
  client: Client,
  server: ServerRow,
  trigger: DigestTrigger,
): Promise<DigestResult> {
  const collected = prepareDigestListings(server);

  const empty: DigestResult = { sent: false, channelOk: false, dmOk: false, listingCount: 0 };
  if (collected.length === 0) {
    return empty;
  }

  const heading = `Daily Listing Digest — ${new Date(now()).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  })}`;
  const message = `${heading}\n\n${formatDigest(collected)}`;

  let channelOk = false;
  let dmOk = false;
  const messages = splitDigestMessage(message);

  if (server.digestMode === 'channel' || server.digestMode === 'both') {
    channelOk = await deliverToChannels(client, server, messages);
  }
  if (server.digestMode === 'dm' || server.digestMode === 'both') {
    dmOk = await deliverToDMs(client, server, messages);
  }

  if (!channelOk && !dmOk) {
    logDigest(server.id, trigger, collected, { channel: false, dm: false });
    sendCriticalAlert(`Digest delivery failed for server ${server.id}`);
    return { sent: false, channelOk, dmOk, listingCount: collected.length };
  }

  setServerWatermark(server.id, now());
  logDigest(server.id, trigger, collected, { channel: channelOk, dm: dmOk });
  return { sent: true, channelOk, dmOk, listingCount: collected.length };
}

async function deliverToChannels(
  client: Client,
  server: ServerRow,
  messages: string[],
): Promise<boolean> {
  if (!server.adminChannelId || messages.length === 0) {
    return false;
  }
  const channel = (await client.channels.fetch(server.adminChannelId)) as TextChannel | null;
  if (!channel || !channel.isTextBased() || !channel.isSendable()) {
    return false;
  }
  try {
    for (const message of messages) {
      await retryWithBackoff(
        () => channel.send({ content: message, allowedMentions: { parse: [] } }),
        {
          attempts: 3,
          baseDelayMs: 1000,
          maxDelayMs: 8000,
        },
      );
    }
    return true;
  } catch {
    return false;
  }
}

async function deliverToDMs(client: Client, server: ServerRow, messages: string[]): Promise<boolean> {
  if (!server.digestDmUserId || messages.length === 0) {
    return false;
  }
  const user = (await client.users.fetch(server.digestDmUserId)) as User | null;
  if (!user) {
    return false;
  }
  try {
    for (const message of messages) {
      await retryWithBackoff(() => user.send({ content: message, allowedMentions: { parse: [] } }), {
        attempts: 3,
        baseDelayMs: 1000,
        maxDelayMs: 8000,
      });
    }
    return true;
  } catch {
    return false;
  }
}

function logDigest(
  serverId: string,
  trigger: DigestTrigger,
  included: ListingRow[],
  results: { channel: boolean; dm: boolean },
): void {
  const db = getDb();
  db.insert(digestLog)
    .values({
      serverId,
      sentAt: now(),
      trigger,
      listingCount: included.length,
      listingIdsIncluded: JSON.stringify(included.map((l) => l.id)),
      deliveryResults: JSON.stringify(results),
    })
    .run();
}

