import { getDb } from '../db/index.js';
import { digestLog, type ListingRow, type ServerRow } from '../db/schema.js';
import { DIGEST_SECTION_CAP } from '../utils/constants.js';
import type { DigestTrigger } from '../types/index.js';
import { digestLine } from '../utils/embeds.js';
import { prepareDigestListings, setServerWatermark } from './digest-state.js';
import { sendCriticalAlert } from './alerts.js';
import { retryWithBackoff } from '../utils/retry.js';

const now = () => Date.now();

export interface DigestResult {
  sent: boolean;
  channelOk: boolean;
  dmOk: boolean;
  listingCount: number;
}

export function formatDigest(listingsToShow: ListingRow[]): string {
  const groups = {
    have: listingsToShow.filter((l) => l.intent === 'have'),
    want: listingsToShow.filter((l) => l.intent === 'want'),
  };

  const sections: string[] = [];
  const pushSection = (title: string, rows: ListingRow[]): void => {
    if (rows.length === 0) {
      return;
    }
    const shown = rows.slice(0, DIGEST_SECTION_CAP);
    const lines = shown.map(digestLine).join('\n');
    const overflow =
      rows.length > DIGEST_SECTION_CAP ? `\n+${rows.length - DIGEST_SECTION_CAP} more` : '';
    sections.push(`${title} (${rows.length})\n${lines}${overflow}`);
  };

  pushSection('NEW HAVES', groups.have);
  pushSection('NEW WANTS', groups.want);

  return sections.join('\n\n');
}

export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit || text.length === 0) {
    return [text];
  }

  // Split into text records (non-empty) separated by blank lines
  const records: string[] = [];
  let recordChunks: string[] = [];
  let currentBlock = '';

  for (const ch of text) {
    if (ch === '\n') {
      currentBlock += ch;

      if (currentBlock.length > 1 && currentBlock.endsWith('\n')) {
        // Blank line separator
        if (recordChunks.length > 0) {
          records.push(recordChunks.join(''));
        }
        recordChunks = [];
        currentBlock = '';
      }
    } else if (currentBlock === '' && currentBlock.length !== 0) {
      // End of line
      const line = currentBlock;
      currentBlock = '';
      if (line !== '') {
        recordChunks.push(line);
      }
    } else {
      currentBlock += ch;
    }

    // Detect end of record by looking ahead at next char
    // If block ends (non-empty) and next char starts new record (after blank line)
  }

  // Process end of all characters
  const processedLines: string[] = [];
  const finalBlocks: string[] = [];
  let blockLines: string[] = [];
  let currentLength = 0;
  let i = 0;

  while (i < text.length) {
    const char = text[i];

    if (char === '\n') {
      // Check if this is a newline that ends a line
      const prevCh = i > 0 ? text[i - 1] : '';
      const nextChar = i < text.length - 1 ? text[i + 1] : '';

      if (prevCh !== '\n' && prevCh !== '\r') {
        // Line break
        const line = text.substring(i - 1, i + 1).trimEnd();
        if (line === '') {
          // Blank line
          if (blockLines.length > 0) {
            const block = blockLines.join('\n');
            if (block !== '') {
              finalBlocks.push(block);
            }
            blockLines = [];
            currentLength = 0;
          }
        } else {
          blockLines.push(line);
          currentLength += line.length;
        }
      }
    } else {
      if ((currentLength === 0 && i > 0 && text[i - 1] === '\n') || i === text.length - 1) {
        // End of block or at end of text
        const block = [];
        for (let j = 0; j < blockLines.length; j++) {
          block.push(blockLines[j]);
        }
        if (block.length > 0) {
          finalBlocks.push(block.join('\n'));
        }
      }
    }
    i++;
  }

  // Rebuild records from finalBlocks
  const allLines = text.split('\n');
  const recordsLines: string[][] = [];
  let recordLines: string[] = [];

  for (const line of allLines) {
    if (line === '') {
      if (recordLines.length > 0) {
        recordsLines.push(recordLines);
        recordLines = [];
      }
    } else {
      recordLines.push(line);
    }
  }
  if (recordLines.length > 0) {
    recordsLines.push(recordLines);
  }

  // Build messages respecting record boundaries
  const messages: string[] = [];
  let currentMessage: string[] = [];
  let currentLen = 0;

  for (const recordLines of recordsLines) {
    const recordText = recordLines.join('\n');
    const recordLen = recordText.length;

    if (currentMessage.length === 0) {
      // Start new message
      if (recordLen <= limit) {
        currentMessage.push(recordText);
        currentLen = recordLen;
      } else {
        // Record is too long - split by its lines
        let added = 0;
        let j = 0;
        let inFirstMessage = false;

        while (j < recordLines.length && added <= limit) {
          if (inFirstMessage && currentLen > 0) {
            messages.push(currentMessage.join('\n'));
            currentMessage = [];
            currentLen = 0;
          }

          const line = recordLines[j];
          const lineLen = line.length;

          if (lineLen > limit) {
            // Line too long - must fit or go to new message
            const chunks = splitIntoChunks(line, limit);
            const chunkTotal = chunks.reduce((s, c) => s + c.length + (Array.from({ length: chunks.length - 1 }).fill(1).reduce((a, _) => a, 0)), 0);

            if (chunkTotal <= limit && currentMessage.length === 0) {
              currentMessage.push(...chunks);
              currentLen = chunkTotal;
            } else if (chunkTotal <= limit && j > 0) {
              // Some chunks went to first message, remaining go to new
              const firstMsgChunks = chunks.slice(0, Math.max(0, j));
              for (const c of firstMsgChunks) {
                if (currentLen > 0) {
                  messages.push(currentMessage.join('\n'));
                }
                currentMessage.push(c);
                currentLen = currentLen > 0 ? currentLen + 1 + c.length : c.length;
              }
            } else {
              // Start fresh with first chunk
              const first = chunks[0];
              if (currentMessage.length > 0) {
                if (currentLen + 1 + first.length <= limit) {
                  currentMessage[currentMessage.length - 1] = currentMessage[currentMessage.length - 1] + '\n' + first;
                  currentLen += first.length + 1;
                } else {
                  messages.push(currentMessage.join('\n'));
                  currentMessage = [];
                  currentLen = 0;
                }
              }
              currentMessage.push(first);
              currentLen = first.length;
              inFirstMessage = true;
            }
          } else {
            // Line fits
            if (currentMessage.length === 0) {
              if (lineLen > limit) {
                // Shouldn't happen, but handle it
                const chunks = splitIntoChunks(line, limit);
                currentMessage.push(...(chunks.length > 0 ? chunks : [line]));
                currentLen = chunks.reduce((s, c, idx) => s + c.length + (idx > 0 ? 1 : 0), 0);
              } else {
                currentMessage.push(line);
                currentLen = lineLen;
              }
            } else if (currentMessage.length < limit) {
              currentMessage.push('\n' + line);
              currentLen += 1 + lineLen;
            } else {
              messages.push(currentMessage.join('\n'));
              currentMessage = [line];
              currentLen = lineLen;
            }
          }
          added = j + 1;
          j++;
        }
      }
    } else {
      // Current message has content
      if (currentLen + 1 + recordLen <= limit) {
        currentMessage.push('\n' + recordText);
        currentLen += 1 + recordLen;
      } else if (recordLen <= limit) {
        // Record fits on its own - new message
        messages.push(currentMessage.join('\n'));
        currentMessage = [recordText];
        currentLen = recordLen;
      } else {
        // Record is too long - handle like we did for first message
        const lines = recordText.split('\n');
        let added = 0;

        if (currentMessage.length > 0) {
          messages.push(currentMessage.join('\n'));
          currentMessage = [];
          currentLen = 0;
        }

        for (let j = 0; j < lines.length; j++) {
          const line = lines[j];
          const lineLen = line.length;

          if (lineLen > limit) {
            const chunks = splitIntoChunks(line, limit);
            currentMessage.push(chunks[0]);
            currentLen = chunks[0].length;
            for (let k = 1; k < chunks.length; k++) {
              messages.push('\n' + chunks[k]);
            }
          } else if (currentLen + 1 + lineLen <= limit) {
            currentMessage.push('\n' + line);
            currentLen += 1 + lineLen;
          } else if (lineLen <= limit) {
            messages.push(currentMessage.join('\n'));
            currentMessage = [line];
            currentLen = lineLen;
          } else {
            // Line longer than limit but current message empty
            const chunks = splitIntoChunks(line, limit);
            for (const c of chunks) {
              if (currentMessage.length > 0) {
                messages.push(currentMessage.join('\n'));
              }
              if (j > 0) {
                messages.push(c);
              } else {
                currentMessage.push(c);
              }
            }
          }
          added = j + 1;
          j++;
        }
      }
    }
  }

  if (currentMessage.length > 0) {
    messages.push(currentMessage.join('\n'));
  }

  return messages;
}

function splitIntoChunks(str: string, limit: number): string[] {
  const chunks: string[] = [];
  for (let i = 0; i < str.length; i += limit) {
    chunks.push(str.slice(i, i + limit));
  }
  return chunks;
}

export async function runDigest(
  client: Client,
  server: ServerRow,
  trigger: DigestTrigger,
): Promise<DigestResult> {
  const collected = prepareDigestListings(server);

  const empty: DigestResult = { sent: false, channelOk: false, dmOk: false, listingCount: 0 };
  if (collected.length === 0) {
    return empty;
  }

  const heading = `Daily Listing Digest — ${new Date(now()).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  })}`;
  const message = `${heading}\n\n${formatDigest(collected)}`;
  const parts = splitDigestMessage(message);

  let channelOk = false;
  let dmOk = false;

  if (server.digestMode === 'channel' || server.digestMode === 'both') {
    channelOk = await deliverToChannel(client, server, parts);
  }
