async function deliverToChannel(
  client: Client,
  server: ServerRow,
  messages: string[],
): Promise<boolean> {
  if (!server.adminChannelId || messages.length === 0) {
    return false;
  }
  try {
    const channel = (await client.channels.fetch(server.adminChannelId)) as TextChannel | null;
    if (!channel || !channel.isTextBased() || !channel.isSendable()) {
      return false;
    }
    for (const msg of messages) {
      await retryWithBackoff(
        () => channel.send({ content: msg, allowedMentions: { parse: [] } }),
        {
          attempts: 3,
          baseDelayMs: 1000,
          maxDelayMs: 8000,
        },
      );
    }
    return true;
  } catch {
    return false;
  }
}

async function deliverToDm(
  client: Client,
  server: ServerRow,
  messages: string[],
): Promise<boolean> {
  if (!server.digestDmUserId || messages.length === 0) {
    return false;
  }
  try {
    const user = (await client.users.fetch(server.digestDmUserId)) as User | null;
    if (!user) {
      return false;
    }
    for (const msg of messages) {
      await retryWithBackoff(() => user.send({ content: msg, allowedMentions: { parse: [] } }), {
