export function formatDigest(listingsToShow: ListingRow[]): string {
  const groups = {
    have: listingsToShow.filter((l) => l.intent === 'have'),
    want: listingsToShow.filter((l) => l.intent === 'want'),
  };

  const sections: string[] = [];
  const pushSection = (title: string, rows: ListingRow[]): void => {
    if (rows.length === 0) {
      return;
    }
    const shown = rows.slice(0, DIGEST_SECTION_CAP);
    const lines = shown.map(digestLine).join('\n');
    const overflow =
      rows.length > DIGEST_SECTION_CAP ? `\n+${rows.length - DIGEST_SECTION_CAP} more` : '';
    sections.push(`${title} (${rows.length})\n${lines}${overflow}`);
  };

  pushSection('NEW HAVES', groups.have);
  pushSection('NEW WANTS', groups.want);

  return sections.join('\n\n');
}

export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit || text.length === 0) {
    return [text];
  }

  const lines = text.split(/\r?\n/);
  const messages: string[] = [];
  const currentBlocks: string[] = [];
  let currentMessageLength = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const isLast = i === lines.length - 1;
    const nextLine = i < lines.length - 1 ? lines[i + 1] : undefined;
    const nextIsBlank = nextLine !== undefined && nextLine === '';
    const isBlank = line === '';
    const isBlankAndNotEmptyNext = isBlank && nextLine !== undefined && !nextIsBlank;
    const isLastOrNextBlank = isLast || (isBlank && nextLine !== undefined && nextIsBlank);

    const proposedLength = currentMessageLength + (currentBlocks.length > 0 ? 1 : 0) + (line === '' ? 0 : line.length) + (!isBlank && i < lines.length - 1 ? 0 : 0);

    if (isBlankAndNotEmptyNext) {
      if (currentBlocks.length > 0) {
        const block = currentBlocks.join('\n');
        if (block.length <= limit) {
          messages.push(block);
        }
        const chunks = chunkString(block, limit);
        for (let j = 0; j < chunks.length; j++) {
          const chunk = chunks[j];
          if (chunk.length > 0) {
            if (messages.length === 0) {
              messages.push(chunk);
            } else {
              messages[messages.length - 1] = messages[messages.length - 1] + '\n' + chunk;
            }
          }
        }
        currentBlocks.length = 0;
        currentMessageLength = 0;
      }
    } else if (!isBlank && currentBlocks.length > 0) {
      currentBlocks.push(line);
      currentMessageLength += 1 + line.length;
    } else if (isBlank && currentBlocks.length === 0) {
      if (i > 0 && lines[i - 1] === '') {
        // Multiple blank lines in a row
      } else {
        const block = currentBlocks.join('\n');
        if (block.length > 0 && block !== '') {
          messages.push(chunkString(block, limit).reduce((acc, c) => {
            if (c.length > 0) {
              return acc.length > 0 ? acc + '\n' + c : c;
            }
            return acc;
          }, ''));
        }
        currentBlocks.length = 0;
        currentMessageLength = 0;
      }
    } else if (!isBlank) {
      currentBlocks.push(line);
      currentMessageLength += 1 + line.length;
    }
  }

  if (currentBlocks.length > 0) {
    const block = currentBlocks.join('\n');
    if (block.length > 0) {
      const chunks = chunkString(block, limit);
      for (let j = 0; j < chunks.length; j++) {
        const chunk = chunks[j];
        if (chunk.length > 0) {
          if (j === 0 && messages.length === 0) {
            messages.push(chunk);
          } else if (chunk.length > limit) {
            chunks.slice(j + 1).forEach(c => {
              if (c.length > 0) messages.push(c);
            });
            messages[messages.length - 1] = messages[messages.length - 1] + '\n' + chunk;
          } else if (chunk.length + 1 <= limit) {
            messages[messages.length - 1] = messages[messages.length - 1] + '\n' + chunk;
          }
        }
      }
    }
  }

  return messages.filter(m => m.length > 0);
}

function chunkString(str: string, limit: number): string[] {
  const result: string[] = [];
  for (let i = 0; i < str.length; i += limit) {
