import { describe, expect, it } from 'vitest';

describe('splitDigestMessage', () => {
  it('returns text unchanged when it fits within limit', () => {
    const result = splitDigestMessage('hello world', 2000);
    expect(result).toHaveLength(1);
    expect(result[0]).toBe('hello world');
  });

  it('splits two 79-char blocks with limit 100 into exactly two blocks', () => {
    const text = 'A'.repeat(79) + '\n\n' + 'B'.repeat(79);
    const result = splitDigestMessage(text, 100);
    console.log('Text:', text.length);
    console.log('Result:', result.map(r => r.length));
    console.log('Messages:', result);
    expect(result).toHaveLength(2);
    expect(result[0].length).toBe(79);
    expect(result[0]).toBe('A'.repeat(79));
    expect(result[1]).toBe('B'.repeat(79));
  });

  it('cuts long lines into pieces of exactly limit chars', () => {
    const text = 'x'.repeat(250);
    const result = splitDigestMessage(text, 100);
    console.log('Result length:', result.length);
    for (let i = 0; i < result.length; i++) {
      expect(result[i].length).toBeLessThanOrEqual(100);
    }
    // Check totals: 100 + 100 + 50 = 250
    const total = result.reduce((sum, r) => sum + r.length, 0);
    expect(total).toBe(250);
  });

  it('preserves original order and content', () => {
    const text = 'a b c\n\nd e f\n\n' + 'g h i';
    const result = splitDigestMessage(text, 1000);
    expect(result[0]).toBe(text);
  });
});

