function splitDigestMessage(text, limit = DISCORD_MESSAGE_MAX_LENGTH) {
  if (text.length <= limit || text.length === 0) {
    return [text];
  }

  const lines = text.split('\n');
  const messages = [];
  const currentBlocks = [];
  let currentMessageLength = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const isLast = i === lines.length - 1;
    const nextLine = i < lines.length - 1 ? lines[i + 1] : undefined;
    const nextIsBlank = nextLine !== undefined && nextLine === '';
    const isBlank = line === '';
    const isBlankAndNotEmptyNext = isBlank && nextLine !== undefined && !nextIsBlank;

    const proposedLength = currentMessageLength + (currentBlocks.length > 0 ? 1 : 0) + (line === '' ? 0 : line.length);

    if (isBlankAndNotEmptyNext) {
      if (currentBlocks.length > 0) {
        const block = currentBlocks.join('\n');
        if (block.length <= limit) {
          messages.push(block);
        } else {
          // Block too long - split by lines
          const blockLines = block.split('\n');
          let addedLen = 0;
          for (let j = 0; j < blockLines.length; j++) {
            const bl = blockLines[j];
            if (bl.length > limit) {
              // This line is too long - commit current first
              if (currentMessageLength > 0) {
                if (currentBlocks.length > 0) {
                  const partialBlock = currentBlocks.join('\n');
                  messages.push(chunkString(partialBlock, limit).reduce((acc, c) => acc + (acc ? '\n' : '') + c, ''));
                  currentBlocks.length = 0;
                  currentMessageLength = 0;
                } else {
                  const partialBlock = bl.slice(0, limit);
                  messages.push(partialBlock);
                  bl = bl.slice(limit);
                }
              }
              // Continue with bl starting fresh
            }
            if (bl.length > 0 && bl.length <= limit) {
              currentBlocks.push(bl);
              currentMessageLength += 1 + bl.length;
            }
            addedLen += bl.length;
          }
        }
        currentBlocks.length = 0;
        currentMessageLength = 0;
      }
    } else if (!isBlank && currentBlocks.length > 0) {
      currentBlocks.push(line);
      currentMessageLength += 1 + line.length;
    } else if (isBlank && currentBlocks.length === 0) {
      if (i > 0 && lines[i - 1] === '') {
        // skip empty
      } else {
        const block = currentBlocks.join('\n');
        if (block.length > 0 && block !== '') {
          const chunks = chunkString(block, limit);
          let msg = '';
          for (let j = 0; j < chunks.length; j++) {
            const c = chunks[j];
            if (c.length > 0) {
              msg += (msg ? '\n' : '') + c;
            }
          }
          if (msg.length > 0) {
            messages.push(msg);
          }
        }
        currentBlocks.length = 0;
        currentMessageLength = 0;
      }
    } else if (!isBlank) {
      currentBlocks.push(line);
      currentMessageLength += 1 + line.length;
    }
  }

  if (currentBlocks.length > 0) {
    const block = currentBlocks.join('\n');
    if (block.length > 0) {
      const chunks = chunkString(block, limit);
      if (chunks.length > 0) {
        messages.push(chunks[0]);
        for (let j = 1; j < chunks.length; j++) {
          if (chunks[j].length > 0) {
            messages.push(chunks[j]);
          }
        }
      }
    }
  }

  return messages.filter(m => m.length > 0);
}

